CREATE TABLE biosequence(sequence_id VARCHAR, header_line_number BIGINT, header_text VARCHAR, residues VARCHAR, length BIGINT, "offset" BIGINT, line_bases INTEGER, line_bytes INTEGER, line_ending VARCHAR, last_line_ending VARCHAR, lines STRUCT(line_number BIGINT, bases INTEGER, line_ending VARCHAR, raw_text VARCHAR)[]);
CREATE TABLE contig(contig_id VARCHAR PRIMARY KEY, length_bp BIGINT, lineage_confidence DOUBLE, taxonomic_lineage VARCHAR[], generated_by VARCHAR, source_files VARCHAR[], topology VARCHAR, member_of VARCHAR[], translation_table INTEGER, CHECK((length_bp >= 1)));
CREATE TABLE contig_collection(collection_id VARCHAR PRIMARY KEY, collection_type VARCHAR, "name" VARCHAR, taxonomic_lineage VARCHAR[], generated_by VARCHAR, source_files VARCHAR[]);
CREATE TABLE feature_record(record_id VARCHAR PRIMARY KEY, line_number BIGINT, raw_text VARCHAR, kind VARCHAR, "scope" VARCHAR, sequence_id VARCHAR, metadata_type VARCHAR, metadata JSON, feature_columns VARCHAR[]);
CREATE TABLE header_record(record_id VARCHAR PRIMARY KEY, line_number BIGINT, raw_text VARCHAR, kind VARCHAR, "scope" VARCHAR, sequence_id VARCHAR, metadata_type VARCHAR, metadata JSON, feature_columns VARCHAR[]);
CREATE TABLE sequence_feature(feature_id VARCHAR PRIMARY KEY, stable_identifiers VARCHAR[], seqid VARCHAR NOT NULL, "source" VARCHAR, "type" VARCHAR, "method" VARCHAR, "start" BIGINT NOT NULL, "end" BIGINT NOT NULL, coordinate_system VARCHAR NOT NULL, score DOUBLE, score_type VARCHAR, strand VARCHAR, phase INTEGER, generated_by VARCHAR, source_files VARCHAR[], is_selected BOOLEAN, is_representative BOOLEAN, product VARCHAR, product_source VARCHAR, "name" VARCHAR, note VARCHAR[], dbxref VARCHAR[], ontology_term VARCHAR[], translated_sequence VARCHAR, parent VARCHAR[], attributes STRUCT("key" VARCHAR, "value" VARCHAR, attribute_cv_id VARCHAR, numeric_value DOUBLE)[], "location" JSON, "target" JSON, CHECK(("start" >= 1)), CHECK(("end" >= "start")), CHECK((coordinate_system IN ('contig', 'protein'))), CHECK((phase BETWEEN 0 AND 2)));
CREATE TABLE source_artifact(uri VARCHAR, sha256 VARCHAR, byte_size BIGINT);

